-- Target: PostgreSQL / Supabase
--
-- PDF 1: 1R1_Roll_List.pdf -> 69 Students -> Class: 1R1 (CSE)
-- PDF 2: 3R_ Student_Roll_List.pdf -> 69 Students -> Class: 3R (CSE)
-- Total Records: 138 (Zero Duplicates)
-- ==============================================================================

BEGIN;

-- 1. RECORD IMPORT BATCHES
VALUES ('816a5c13-6210-4c7f-929b-13d014880afb', '1R1_Roll_List.pdf', '11111111-1111-1111-1111-111111111111'::uuid, 69, 69, 0, 0, 'COMPLETED');

VALUES ('da639868-aa1a-4c5c-8634-b532ef0bda46', '3R_ Student_Roll_List.pdf', 'ac46eda9-4dd3-4432-ac69-d4b91b61aa4d'::uuid, 69, 69, 0, 0, 'COMPLETED');

-- 2. INSERT STUDENTS FROM PDF 1 (1R1_Roll_List.pdf - Class: 1R1, Department: CSE, Year: 1, Div: A)
ON CONFLICT (sis_id) DO UPDATE SET
  roll_no = EXCLUDED.roll_no,
  full_name = EXCLUDED.full_name,
  class_id = EXCLUDED.class_id,
  department_id = EXCLUDED.department_id,
  year = EXCLUDED.year,
  division = EXCLUDED.division,
  updated_at = now();

-- 3. INSERT STUDENTS FROM PDF 2 (3R_ Student_Roll_List.pdf - Class: 3R, Department: CSE, Year: 3, Div: 1)
ON CONFLICT (sis_id) DO UPDATE SET
  roll_no = EXCLUDED.roll_no,
  full_name = EXCLUDED.full_name,
  class_id = EXCLUDED.class_id,
  department_id = EXCLUDED.department_id,
  year = EXCLUDED.year,
  division = EXCLUDED.division,
  updated_at = now();

COMMIT;